//! User interface layer for Nextcloud Desktop and Mobile applications.
//!
//! # Architecture & Platform Support
//!
//! - **Desktop (GTK 4 / Libadwaita)**: The desktop application is the primary
//!   implementation and **source of truth** for all Nextcloud client features,
//!   including file management, synchronization controls, account switching,
//!   theming customization, and system tray integration. See the `desktop` module.
//! - **Android (UniFFI)**: Android bindings match the desktop application's
//!   architecture and functionality via foreign function interfaces generated by UniFFI.
//!   The Android implementation is currently **TODO / work-in-progress**. See the `android` feature module.

#![deny(missing_docs)]
#![forbid(unsafe_code)]

pub mod controller;
pub mod error;
pub mod headless;
pub mod model;
pub mod widget;

#[cfg(any(feature = "desktop", feature = "gtk", feature = "tray"))]
pub mod desktop;

#[cfg(feature = "android")]
pub mod android;

#[cfg(feature = "gtk")]
pub use desktop::*;

#[cfg(feature = "android")]
uniffi::setup_scaffolding!("nextcloud_desktop_ui");

pub use controller::DesktopUiController;
#[cfg(feature = "gtk")]
pub use desktop::gtk_app::{launch_gtk_application, suppress_gtk_logs};
#[cfg(feature = "tray")]
pub use desktop::tray::{TrayAction, spawn_app_bar_tray};
pub use error::UiError;
pub use headless::run_headless;
pub use model::{
    FileSyncStatus, FileViewItem, FileViewMode, NavigationPage, PathSegment, TransferItem,
};
#[cfg(feature = "gtk")]
pub use widget::ItemCollectionView;
pub use widget::{FileExplorerBackend, ViewComponent};
